:root {
  color-scheme: light;
  --ink: #203842;
  --muted: #647b7c;
  --paper: #fffdf5;
  --mint: #d6eee0;
  --coral: #ef866d;
  --line: #dce5d8;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 40px 18px;
  display: grid;
  place-items: center;
  background-color: #203842;
  background-image: linear-gradient(45deg, #2a4650 25%, transparent 25%), linear-gradient(-45deg, #2a4650 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #2a4650 75%), linear-gradient(-45deg, transparent 75%, #2a4650 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
}
button, input, textarea { font: inherit; }
.app-card {
  width: min(100%, 590px);
  padding: 30px 34px 20px;
  border: 3px solid var(--ink);
  border-radius: 8px;
  background: var(--paper);
  box-shadow: 8px 8px 0 #132831;
}
.header { display: flex; align-items: center; gap: 14px; margin-bottom: 24px; }
.pixel-mark { display: grid; place-items: center; width: 48px; height: 48px; background: var(--coral); color: white; font-size: 28px; box-shadow: 4px 4px 0 var(--ink); }
.eyebrow { margin: 0 0 2px; color: var(--muted); font-size: 13px; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 0; font-size: 30px; line-height: 1.15; letter-spacing: -.04em; }
.note-form { display: grid; gap: 9px; }
label { font-weight: 750; }
.label-hint, .section-note { color: var(--muted); font-size: 14px; font-weight: 500; }
textarea, input { width: 100%; padding: 12px 13px; border: 2px solid var(--line); border-radius: 5px; outline: none; background: white; color: var(--ink); }
textarea { min-height: 82px; resize: vertical; }
textarea:focus, input:focus { border-color: #4f9275; box-shadow: 0 0 0 3px #d6eee0; }
.add-button, .clear-button, .tag-chip { cursor: pointer; }
.add-button { justify-self: start; margin-top: 4px; padding: 11px 17px; border: 2px solid var(--ink); border-radius: 5px; background: var(--coral); color: #fff; font-weight: 800; box-shadow: 3px 3px 0 var(--ink); }
.add-button span { font-size: 21px; vertical-align: -1px; }
button:hover { filter: brightness(.96); }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
button:focus-visible { outline: 3px solid #4f9275; outline-offset: 3px; }
.tag-section { margin: 27px 0 23px; padding: 17px 0 0; border-top: 2px dashed var(--line); }
h2 { margin: 0; font-size: 18px; }
.tag-section h2 { margin-bottom: 12px; }
.tag-list { display: flex; flex-wrap: wrap; gap: 8px; }
.tag-chip { padding: 7px 10px; border: 1px solid #a9cdb7; border-radius: 4px; background: var(--mint); color: var(--ink); font-size: 14px; }
.tag-chip[aria-pressed="true"] { border-color: var(--ink); background: var(--ink); color: white; }
.tag-count { margin-left: 5px; color: var(--muted); font-size: 13px; }
.tag-chip[aria-pressed="true"] .tag-count { color: #d6eee0; }
.notes-title-row { display: flex; justify-content: space-between; align-items: center; }
.note-count { color: var(--muted); font-size: 14px; }
.active-filter { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-top: 12px; padding: 9px 11px; border-left: 4px solid var(--coral); background: #fff0e8; }
.clear-button { padding: 5px 8px; border: 1px solid var(--ink); border-radius: 3px; background: transparent; color: var(--ink); font-size: 14px; }
.notes-list { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
.note { padding: 14px; border: 1px solid var(--line); border-left: 4px solid #74a98b; border-radius: 4px; background: white; }
.note-text { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.5; }
.note-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 11px; }
.note-tag { color: var(--muted); font-size: 13px; }
.note-tag::before { content: "#"; color: #4f9275; }
.empty-state { margin: 18px 0 5px; padding: 19px 12px; border: 1px dashed #bdcec1; border-radius: 4px; color: var(--muted); text-align: center; }
.empty-state span { color: var(--coral); }
footer { margin-top: 24px; color: var(--muted); font-size: 13px; text-align: center; }
footer span { color: var(--coral); }
@media (max-width: 420px) {
  body { padding: 22px 12px; }
  .app-card { padding: 22px 18px 17px; }
  h1 { font-size: 27px; }
}

const form = document.querySelector('#note-form');
const textInput = document.querySelector('#note-text');
const tagsInput = document.querySelector('#note-tags');
const tagList = document.querySelector('#tag-list');
const notesList = document.querySelector('#notes-list');
const noteCount = document.querySelector('#note-count');
const emptyState = document.querySelector('#empty-state');
const activeFilter = document.querySelector('#active-filter');
const filterName = document.querySelector('#filter-name');
const clearFilter = document.querySelector('#clear-filter');

let notes = [];
let selectedTag = null;

function getTagCounts() {
  const counts = new Map();
  notes.forEach(note => note.tags.forEach(tag => counts.set(tag, (counts.get(tag) || 0) + 1)));
  return counts;
}

function render() {
  const counts = getTagCounts();
  tagList.replaceChildren();
  [...counts.entries()].sort(([a], [b]) => a.localeCompare(b)).forEach(([tag, count]) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'tag-chip';
    button.setAttribute('aria-pressed', String(selectedTag === tag));
    button.setAttribute('aria-label', `${tag}, ${count} ${count === 1 ? 'note' : 'notes'}`);
    button.append(document.createTextNode(tag));
    const amount = document.createElement('span');
    amount.className = 'tag-count';
    amount.setAttribute('aria-hidden', 'true');
    amount.textContent = count;
    button.append(amount);
    button.addEventListener('click', () => {
      selectedTag = selectedTag === tag ? null : tag;
      render();
    });
    tagList.append(button);
  });

  const visibleNotes = selectedTag ? notes.filter(note => note.tags.includes(selectedTag)) : notes;
  notesList.replaceChildren();
  [...visibleNotes].reverse().forEach(note => {
    const item = document.createElement('li');
    item.className = 'note';
    const body = document.createElement('p');
    body.className = 'note-text';
    body.textContent = note.text;
    item.append(body);
    if (note.tags.length) {
      const tags = document.createElement('div');
      tags.className = 'note-tags';
      note.tags.forEach(tag => {
        const label = document.createElement('span');
        label.className = 'note-tag';
        label.textContent = tag;
        tags.append(label);
      });
      item.append(tags);
    }
    notesList.append(item);
  });

  noteCount.textContent = `${visibleNotes.length} ${visibleNotes.length === 1 ? 'note' : 'notes'}`;
  emptyState.hidden = visibleNotes.length > 0;
  emptyState.textContent = notes.length && selectedTag ? `No notes tagged “${selectedTag}”.` : 'Your page is still blank. Add a note to get started ✎';
  activeFilter.hidden = !selectedTag;
  filterName.textContent = selectedTag ? `#${selectedTag}` : '';
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = textInput.value.trim();
  if (!text) {
    textInput.focus();
    return;
  }
  const tags = [...new Set(tagsInput.value.split(',').map(tag => tag.trim().toLowerCase()).filter(Boolean))];
  notes.unshift({ text, tags });
  selectedTag = null;
  form.reset();
  render();
  textInput.focus();
});

clearFilter.addEventListener('click', () => {
  selectedTag = null;
  render();
});

render();
